def _mini(side, typ, lab, K=100, p=8):
    return ('<div class="card chartw"><b class="ct" style="margin:0">' + lab + '</b>'
            + CHART([dict(pts=POS(side, typ, K, p), c='#0f9d90' if side > 0 else '#ff6a4d')], 60, 140, -40, 40, [60, 100, 140], [-30, 0, 30], W=560, H=176, fs=17) + '</div>')


